"""A user's address waiting for its link (generated by Shikshya, PX.303). No row means confirmed:
Google sign-in, seeded accounts and staff never get one. The address itself stays on the user; the link is tied to it
by core.py."""
from django.conf import settings
from django.db import models


class PendingEmail(models.Model):
    user = models.OneToOneField(settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="pending_email")
    sent_at = models.DateTimeField()

    def __str__(self):
        return "pending:%s" % self.user_id
